export function saveHistory(result) {
  try {
    const history = JSON.parse(localStorage.getItem('chronos_history') || '[]');
    history.push({
      date: new Date().toISOString(),
      bioAge: result.bioAge,
      healthScore: result.healthScore,
      chronologicalAge: result.chronologicalAge,
      dimensions: result.dimensions.map(d => ({ name: d.name, score: d.score }))
    });
    if (history.length > 20) history.shift();
    localStorage.setItem('chronos_history', JSON.stringify(history));
  } catch (e) {
    console.error('Save history failed', e);
  }
}

export function getHistory() {
  try {
    return JSON.parse(localStorage.getItem('chronos_history') || '[]');
  } catch (e) {
    return [];
  }
}