import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend } from 'recharts';
import { DIMENSIONS, calculateBioAge, getInsights, saveHistory, getHistory, adviceDetailMap } from './engine';
import './App.css';

const CONSENT_KEY = 'chronos_consent_accepted';

